alter policy nexora_courses_enrolled_select on nexora.courses using ((select nexora_private.is_admin()) or ((select nexora_private.is_member()) and exists (select 1 from nexora.enrollments e where e.course_id=courses.id and e.user_id=(select auth.uid()) and e.status=any(array['active'::text,'completed'::text]))));
alter policy nexora_modules_enrolled_select on nexora.modules using ((select nexora_private.is_admin()) or ((select nexora_private.is_member()) and exists (select 1 from nexora.enrollments e where e.course_id=modules.course_id and e.user_id=(select auth.uid()) and e.status=any(array['active'::text,'completed'::text]))));
alter policy nexora_lessons_enrolled_select on nexora.lessons using ((select nexora_private.is_admin()) or ((select nexora_private.is_member()) and exists (select 1 from nexora.modules m join nexora.enrollments e on e.course_id=m.course_id where m.id=lessons.module_id and e.user_id=(select auth.uid()) and e.status=any(array['active'::text,'completed'::text]))));
alter policy nexora_assessments_enrolled_select on nexora.assessments using ((select nexora_private.is_admin()) or ((select nexora_private.is_member()) and exists (select 1 from nexora.enrollments e where e.course_id=assessments.course_id and e.user_id=(select auth.uid()) and e.status=any(array['active'::text,'completed'::text]))));
alter policy nexora_questions_enrolled_select on nexora.questions using ((select nexora_private.is_admin()) or ((select nexora_private.is_member()) and exists (select 1 from nexora.assessments a join nexora.enrollments e on e.course_id=a.course_id where a.id=questions.assessment_id and e.user_id=(select auth.uid()) and e.status=any(array['active'::text,'completed'::text]))));
alter policy nexora_projects_enrolled_select on nexora.projects using ((select nexora_private.is_admin()) or ((select nexora_private.is_member()) and exists (select 1 from nexora.enrollments e where e.course_id=projects.course_id and e.user_id=(select auth.uid()) and e.status=any(array['active'::text,'completed'::text]))));
alter policy nexora_assets_enrolled_select on nexora.lesson_assets using (is_student_visible and ((select nexora_private.is_admin()) or ((select nexora_private.is_member()) and exists (select 1 from nexora.lessons l join nexora.modules m on m.id=l.module_id join nexora.enrollments e on e.course_id=m.course_id where l.id=lesson_assets.lesson_id and e.user_id=(select auth.uid()) and e.status=any(array['active'::text,'completed'::text])))));
